 84	    constructor(posthog: PostHog) {
 85	        this.posthog = posthog;
 86	    }
 87	
 88	    public async init(anonymity: Anonymity | boolean = Anonymity.Anonymous) {
 89	        this.initialised = false;
 90	        this.enabled = false;
 91	        this.setAnonymity(typeof anonymity === "boolean" ?
 92	            (anonymity ? Anonymity.Anonymous : Anonymity.Pseudonymous) : anonymity);
 93	
 94	        const posthogConfig = SdkConfig.get()["posthog"];
 95	        if (typeof posthogConfig?.projectApiKey === "string" && posthogConfig.projectApiKey.trim() &&
 96	            typeof posthogConfig?.apiHost === "string" && posthogConfig.apiHost.trim()) {
 97	            // Update the redacted current location before initialising posthog, as posthog.init triggers
 98	            // an immediate pageview event which calls the sanitize_properties callback
 99	            await this.updateRedactedCurrentLocation();
100	
101	            this.posthog.init(posthogConfig.projectApiKey, {
102	                api_host: posthogConfig.apiHost,
103	                autocapture: false,
104	                mask_all_text: true,
105	                mask_all_element_attributes: true,
106	                sanitize_properties: this.sanitizeProperties.bind(this),
107	            });
108	            this.initialised = true;
109	            this.enabled = true;
110	        }
111	    }
112	
113	    private async updateRedactedCurrentLocation() {
114	        // TODO only calculate this when the location changes as its expensive
115	        const { origin, hash, pathname } = window.location;
116	        this.redactedCurrentLocation = await getRedactedCurrentLocation(
117	            origin, hash, pathname, this.anonymity);
118	    }
119	
120	    private sanitizeProperties(properties: posthog.Properties, _: string): posthog.Properties {
121	        // Sanitize posthog's built in properties which leak PII e.g. url reporting
122	        // see utils.js _.info.properties in posthog-js
123	
124	        // this.redactedCurrentLocation needs to have been updated prior to reaching this point as
125	        // updating it involves async, which this callback is not
126	        properties['$current_url'] = this.redactedCurrentLocation;
127	
128	        if (this.anonymity === Anonymity.Anonymous) {
129	            // drop referrer information for anonymous users
130	            properties['$referrer'] = null;
131	            properties['$referring_domain'] = null;
132	            properties['$initial_referrer'] = null;
133	            properties['$initial_referring_domain'] = null;
134	
135	            // drop device ID, which is a UUID persisted in local storage
136	            properties['$device_id'] = null;
137	        }
138	
139	        return properties;
140	    }
